For sure.

I agree that it's less readable, but it saves us some allocations and in general we avoid allocations in BCL if we can. Having said that, I am going to mark it as resolved.

```cs
internal class Program
{
    static void Main(string[] args) => BenchmarkSwitcher.FromAssembly(typeof(Program).Assembly).Run(args);
}

public class Benchmarks
{
    const int MaxNameLength = 30;
    const string NamePrefix = "/dotnet_";

    [Benchmark(Baseline = true)]
    public string Current()
        => string.Create(MaxNameLength, 0, (span, state) =>
        {
            Span<char> guid = stackalloc char[32];
            Guid.NewGuid().TryFormat(guid, out int charsWritten, "N");
            NamePrefix.CopyTo(span);
            guid.Slice(0, MaxNameLength - NamePrefix.Length).CopyTo(span.Slice(NamePrefix.Length));
        });

    [Benchmark]
    public string Proposed() => $"/dotnet_{Guid.NewGuid()}".Substring(0, MaxNameLength);
}
```

